84	   * root directories).
85	   * 
86	   * The AsyncDiskServices uses one ThreadPool per volume to do the async
87	   * disk operations.
88	   */
89	  FsDatasetAsyncDiskService(DataNode datanode, FsDatasetImpl fsdatasetImpl) {
90	    this.datanode = datanode;
91	    this.fsdatasetImpl = fsdatasetImpl;
92	    this.threadGroup = new ThreadGroup(getClass().getSimpleName());
93	  }
