95	  private void addExecutorForVolume(final FsVolumeImpl volume) {
96	    ThreadFactory threadFactory = new ThreadFactory() {
97	      int counter = 0;
98	
99	      @Override
100	      public Thread newThread(Runnable r) {
101	        int thisIndex;
102	        synchronized (this) {
103	          thisIndex = counter++;
104	        }
105	        Thread t = new Thread(threadGroup, r);
106	        t.setName("Async disk worker #" + thisIndex +
107	            " for volume " + volume);
108	        return t;
109	      }
110	    };
111	
112	    ThreadPoolExecutor executor = new ThreadPoolExecutor(
113	        CORE_THREADS_PER_VOLUME, MAXIMUM_THREADS_PER_VOLUME,
114	        THREADS_KEEP_ALIVE_SECONDS, TimeUnit.SECONDS,
115	        new LinkedBlockingQueue<Runnable>(), threadFactory);
116	
117	    // This can reduce the number of running threads
118	    executor.allowCoreThreadTimeOut(true);
119	    executors.put(volume.getStorageID(), executor);
120	  }
