272	    public void handle(ExtendedBlock block, IOException e) {
273	      FsVolumeSpi volume = scanner.volume;
274	      if (e == null) {
275	        LOG.trace("Successfully scanned {} on {}", block, volume);
276	        return;
277	      }
278	      // If the block does not exist anymore, then it's not an error.
279	      if (!volume.getDataset().contains(block)) {
280	        LOG.debug("Volume {}: block {} is no longer in the dataset.",
281	            volume, block);
282	        return;
283	      }
284	      // If the block exists, the exception may due to a race with write:
285	      // The BlockSender got an old block path in rbw. BlockReceiver removed
286	      // the rbw block from rbw to finalized but BlockSender tried to open the
287	      // file before BlockReceiver updated the VolumeMap. The state of the
288	      // block can be changed again now, so ignore this error here. If there
289	      // is a block really deleted by mistake, DirectoryScan should catch it.
290	      if (e instanceof FileNotFoundException ) {
291	        LOG.info("Volume {}: verification failed for {} because of " +
292	                "FileNotFoundException.  This may be due to a race with write.",
293	            volume, block);
294	        return;
295	      }
296	      LOG.warn("Reporting bad {} on {}", block, volume);
297	      scanner.datanode.handleBadBlock(block, e, true);
298	    }
299	  }
