35	import static org.apache.hadoop.hdfs.DFSConfigKeys.DFS_NAMENODE_AVAILABLE_SPACE_RACK_FAULT_TOLERANT_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY;
36	
37	/**
38	 * Space balanced rack fault tolerant block placement policy.
39	 */
40	public class AvailableSpaceRackFaultTolerantBlockPlacementPolicy
41	    extends BlockPlacementPolicyRackFaultTolerant {
42	
43	  private static final Logger LOG = LoggerFactory
44	      .getLogger(AvailableSpaceRackFaultTolerantBlockPlacementPolicy.class);
45	  private static final Random RAND = new Random();
46	  private int balancedPreference = (int) (100
47	      * DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_RACK_FAULT_TOLERANT_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_DEFAULT);
48	
49	  @Override
50	  public void initialize(Configuration conf, FSClusterStats stats,
51	      NetworkTopology clusterMap, Host2NodesMap host2datanodeMap) {
52	    super.initialize(conf, stats, clusterMap, host2datanodeMap);
53	    float balancedPreferencePercent = conf.getFloat(
54	        DFS_NAMENODE_AVAILABLE_SPACE_RACK_FAULT_TOLERANT_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY,
55	        DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_RACK_FAULT_TOLERANT_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_DEFAULT);
56	
57	    LOG.info("Available space rack fault tolerant block placement policy "
58	        + "initialized: "
59	        + DFSConfigKeys.DFS_NAMENODE_AVAILABLE_SPACE_RACK_FAULT_TOLERANT_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
60	        + " = " + balancedPreferencePercent);
61	
62	    if (balancedPreferencePercent > 1.0) {
63	      LOG.warn("The value of "
64	          + DFS_NAMENODE_AVAILABLE_SPACE_RACK_FAULT_TOLERANT_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
65	          + " is greater than 1.0 but should be in the range 0.0 - 1.0");
66	    }
67	    if (balancedPreferencePercent < 0.5) {
68	      LOG.warn("The value of "
69	          + DFS_NAMENODE_AVAILABLE_SPACE_RACK_FAULT_TOLERANT_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
70	          + " is less than 0.5 so datanodes with more used percent will"
71	          + " receive  more block allocations.");
72	    }
73	    balancedPreference = (int) (100 * balancedPreferencePercent);
74	  }
75	
76	  @Override
77	  protected DatanodeDescriptor chooseDataNode(final String scope,
78	      final Collection<Node> excludedNode, StorageType type) {
79	    // only the code that uses DFSNetworkTopology should trigger this code path.
80	    Preconditions.checkArgument(clusterMap instanceof DFSNetworkTopology);
81	    DFSNetworkTopology dfsClusterMap = (DFSNetworkTopology) clusterMap;
82	    DatanodeDescriptor a = (DatanodeDescriptor) dfsClusterMap
83	        .chooseRandomWithStorageTypeTwoTrial(scope, excludedNode, type);
84	    DatanodeDescriptor b = (DatanodeDescriptor) dfsClusterMap
85	        .chooseRandomWithStorageTypeTwoTrial(scope, excludedNode, type);
86	    return select(a, b);
87	  }
88	
89	  @Override
90	  protected DatanodeDescriptor chooseDataNode(final String scope,
91	      final Collection<Node> excludedNode) {
92	    DatanodeDescriptor a =
93	        (DatanodeDescriptor) clusterMap.chooseRandom(scope, excludedNode);
94	    DatanodeDescriptor b =
95	        (DatanodeDescriptor) clusterMap.chooseRandom(scope, excludedNode);
96	    return select(a, b);
97	  }
98	
99	  private DatanodeDescriptor select(DatanodeDescriptor a,
100	      DatanodeDescriptor b) {
101	    if (a != null && b != null) {
102	      int ret = compareDataNode(a, b);
103	      if (ret == 0) {
104	        return a;
105	      } else if (ret < 0) {
106	        return (RAND.nextInt(100) < balancedPreference) ? a : b;
107	      } else {
108	        return (RAND.nextInt(100) < balancedPreference) ? b : a;
109	      }
110	    } else {
111	      return a == null ? b : a;
112	    }
113	  }
114	
115	  /**
116	   * Compare the two data nodes.
117	   */
118	  protected int compareDataNode(final DatanodeDescriptor a,
119	      final DatanodeDescriptor b) {
120	    if (a.equals(b)
121	        || Math.abs(a.getDfsUsedPercent() - b.getDfsUsedPercent()) < 5) {
122	      return 0;
123	    }
124	    return a.getDfsUsedPercent() < b.getDfsUsedPercent() ? -1 : 1;
125	  }
126	}

