index 378b83d1..0e15c20e 100644
--- a/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/ipc/CallerContext.java
+++ b/hadoop-common-project/hadoop-common/src/main/java/org/apache/hadoop/ipc/CallerContext.java
@@ -29,6 +29,7 @@
 import java.util.Collections;
 import java.util.HashSet;
 import java.util.Set;
+import java.util.regex.Pattern;

 import static org.apache.hadoop.fs.CommonConfigurationKeysPublic.HADOOP_CALLER_CONTEXT_SEPARATOR_DEFAULT;
 import static org.apache.hadoop.fs.CommonConfigurationKeysPublic.HADOOP_CALLER_CONTEXT_SEPARATOR_KEY;
@@ -228,6 +229,39 @@ public Builder append(String key, String value) {
       return this;
     }

+    /**
+     * Append new field which contains key and value to the context
+     * only when the key is not already present in the context.
+     * @param key the key of field.
+     * @param value the value of field.
+     * @return the builder.
+     */
+    public Builder appendIfAbsent(String key, String value) {
+      if (isValid(key) && isValid(value) && !containsKey(key)) {
+        return append(key, value);
+      }
+      return this;
+    }
+
+    /**
+     * Whether the key is already present in the context.
+     * @param key the key of field.
+     * @return true if the key is already present in the context.
+     */
+    private boolean containsKey(String key) {
+      if (sb.length() == 0) {
+        return false;
+      }
+      String keyPrefix = key + KEY_VALUE_SEPARATOR;
+      for (String field
+          : sb.toString().split(Pattern.quote(fieldSeparator))) {
+        if (field.startsWith(keyPrefix)) {
+          return true;
+        }
+      }
+      return false;
+    }
+
     public CallerContext build() {
       return new CallerContext(this);
     }

