/**
 * Opens a rolling leveldb instance. If the existing leveldb files are
 * missing or corrupt and hence cannot be opened, the database is recreated
 * so that service startup is not blocked by a broken store.
 */
private DB open(Path rollingInstanceDBPath, Options options)
    throws IOException {
  File dbFile = new File(rollingInstanceDBPath.toUri().getPath());
  try {
    return factory.open(dbFile, options);
  } catch (Exception exc) {
    LOG.warn("Failed to open leveldb instance " + dbFile
        + ", recreating it", exc);
    factory.destroy(dbFile, options);
    return factory.open(dbFile, options);
  }
}

