  @Test
  public void testInsertForPreviousPeriodAfterRollPeriodRollsDB()
      throws Exception {

    rollingLevelDB.init(conf);
    long now = rollingLevelDB.currentTimeMillis();
    now = rollingLevelDB.computeCurrentCheckMillis(now);
    rollingLevelDB.setCurrentTimeMillis(now);
    DB db = rollingLevelDB.getDBForStartTime(now - 1);
    long startTime = rollingLevelDB.getStartTimeFor(db);
    Assert.assertEquals("Received level db for incorrect start time",
        rollingLevelDB.computeCurrentCheckMillis(now - 1),
        startTime);
  }

  @Test
  public void testDbRecreatedWhenFilesAreCorrupt() throws Exception {
    rollingLevelDB.init(conf);
    long now = rollingLevelDB.currentTimeMillis();
    DB db = rollingLevelDB.getDBForStartTime(now);
    Assert.assertNotNull("Failed to create leveldb", db);
    rollingLevelDB.stop();

    // corrupt all the files of the existing leveldb instance
    Path dbRoot = new Path(
        conf.get(YarnConfiguration.TIMELINE_SERVICE_LEVELDB_PATH),
        RollingLevelDBTimelineStore.FILENAME);
    FileStatus[] statuses = lfs.globStatus(new Path(dbRoot, "Test.*"));
    Assert.assertNotNull(statuses);
    Assert.assertEquals(1, statuses.length);
    for (FileStatus status : lfs.listStatus(statuses[0].getPath())) {
      FSDataOutputStream out = lfs.create(status.getPath(), true);
      out.write("corrupt".getBytes(StandardCharsets.UTF_8));
      out.close();
    }

    // the corrupt leveldb instance should be recreated instead of
    // failing the initialization
    MyRollingLevelDB recovered = new MyRollingLevelDB();
    recovered.setCurrentTimeMillis(now);
    recovered.init(conf);
    db = recovered.getDBForStartTime(now);
    Assert.assertNotNull("Corrupt leveldb was not recreated", db);
    recovered.stop();
  }
}

