61	class FsDatasetAsyncDiskService {
62	  public static final Logger LOG =
63	      LoggerFactory.getLogger(FsDatasetAsyncDiskService.class);
64	  
65	  // ThreadPool core pool size
66	  private static final int CORE_THREADS_PER_VOLUME = 1;
67	  // ThreadPool maximum pool size
68	  private static final int MAXIMUM_THREADS_PER_VOLUME = 4;
69	  // ThreadPool keep-alive time for threads over core pool size
70	  private static final long THREADS_KEEP_ALIVE_SECONDS = 60; 
71	  
72	  private final DataNode datanode;
73	  private final FsDatasetImpl fsdatasetImpl;
74	  private Map<String, ThreadPoolExecutor> executors
75	      = new HashMap<String, ThreadPoolExecutor>();
76	  private Map<String, Set<Long>> deletedBlockIds 
77	      = new HashMap<String, Set<Long>>();
78	  private static final int MAX_DELETED_BLOCKS = 64;
79	  private int numDeletedBlocks = 0;
80	  
81	  /**
82	   * Create a AsyncDiskServices with a set of volumes (specified by their
83	   * root directories).
84	   * 
85	   * The AsyncDiskServices uses one ThreadPool per volume to do the async
86	   * disk operations.
87	   */
88	  FsDatasetAsyncDiskService(DataNode datanode, FsDatasetImpl fsdatasetImpl) {
89	    this.datanode = datanode;
90	    this.fsdatasetImpl = fsdatasetImpl;
91	  }
92	
93	  private void addExecutorForVolume(final FsVolumeImpl volume) {
94	    ThreadFactory threadFactory = new ThreadFactory() {
95	      int counter = 0;
96	
97	      @Override
98	      public Thread newThread(Runnable r) {
99	        int thisIndex;
100	        synchronized (this) {
101	          thisIndex = counter++;
102	        }
103	        Thread t = new Thread(r);
104	        t.setName("Async disk worker #" + thisIndex +
105	            " for volume " + volume);
106	        return t;
107	      }
108	    };
109	
110	    ThreadPoolExecutor executor = new ThreadPoolExecutor(
111	        CORE_THREADS_PER_VOLUME, MAXIMUM_THREADS_PER_VOLUME,
112	        THREADS_KEEP_ALIVE_SECONDS, TimeUnit.SECONDS,
113	        new LinkedBlockingQueue<Runnable>(), threadFactory);
114	
115	    // This can reduce the number of running threads
116	    executor.allowCoreThreadTimeOut(true);
117	    executors.put(volume.getStorageID(), executor);
118	  }
