43	/**
44	 * This class provides the basic functionality to sync two FileSystems based on
45	 * the snapshot diff report. More specifically, we have the following settings:
46	 * 1. Both the source and target FileSystem must be DistributedFileSystem or
47	 * (s)WebHdfsFileSystem
48	 * 2. Two snapshots (e.g., s1 and s2) have been created on the source FS.
49	 * The diff between these two snapshots will be copied to the target FS.
50	 * 3. The target has the same snapshot s1. No changes have been made on the
51	 * target since s1. All the files/directories in the target are the same with
52	 * source.s1
53	 */
54	class DistCpSync {
55	  private DistCpContext context;
56	  private Configuration conf;
57	  // diffMap maps snapshot diff op type to a list of diff ops.
58	  // It's initially created based on the snapshot diff. Then the individual
59	  // diff stored there maybe modified instead of copied by the distcp algorithm
60	  // afterwards, for better performance.
61	  //
62	  private EnumMap<SnapshotDiffReport.DiffType, List<DiffInfo>> diffMap;
63	  private DiffInfo[] renameDiffs;
64	  // entries which are marked deleted because of rename to a excluded target
65	  // path
66	  private List<DiffInfo> deletedByExclusionDiffs;
67	  private CopyFilter copyFilter;
68	
69	  DistCpSync(DistCpContext context, Configuration conf) {
70	    this.context = context;
71	    this.conf = conf;
72	    this.copyFilter = CopyFilter.getCopyFilter(conf);
73	    this.copyFilter.initialize();
74	  }
75	
76	  @VisibleForTesting
77	  public void setCopyFilter(CopyFilter copyFilter) {
78	    this.copyFilter = copyFilter;
79	  }
80	
81	  private boolean isRdiff() {
82	    return context.shouldUseRdiff();
83	  }
84	
85	  /**
86	   * Check if three conditions are met before sync.
87	   * 1. Only one source directory.
88	   * 2. Both source and target file system are DFS or WebHdfs.
89	   * 3. There is no change between from and the current status in target
90	   *    file system.
91	   *  Throw exceptions if first two aren't met, and return false to fallback to
92	   *  default distcp if the third condition isn't met.
93	   */
94	  private boolean preSyncCheck() throws IOException {
95	    List<Path> sourcePaths = context.getSourcePaths();
96	    if (sourcePaths.size() != 1) {
97	      // we only support one source dir which must be a snapshottable directory
98	      throw new IllegalArgumentException(sourcePaths.size()
99	          + " source paths are provided");
100	    }
101	    final Path sourceDir = sourcePaths.get(0);
102	    final Path targetDir = context.getTargetPath();
103	
104	    final FileSystem srcFs = sourceDir.getFileSystem(conf);
105	    final FileSystem tgtFs = targetDir.getFileSystem(conf);
106	    final FileSystem snapshotDiffFs = isRdiff() ? tgtFs : srcFs;
107	    final Path snapshotDiffDir = isRdiff() ? targetDir : sourceDir;
108	
109	    // currently we require both the source and the target file system are
110	    // DistributedFileSystem or (S)WebHdfsFileSystem.
111	    if (!(srcFs instanceof DistributedFileSystem
112	            || srcFs instanceof WebHdfsFileSystem)) {
113	      throw new IllegalArgumentException("Unsupported source file system: "
114	          + srcFs.getScheme() + "://. " +
115	          "Supported file systems: hdfs://, webhdfs:// and swebhdfs://.");
116	    }
117	    if (!(tgtFs instanceof DistributedFileSystem
118	        || tgtFs instanceof WebHdfsFileSystem)) {
119	      throw new IllegalArgumentException("Unsupported target file system: "
120	          + tgtFs.getScheme() + "://. " +
121	          "Supported file systems: hdfs://, webhdfs:// and swebhdfs://.");
122	    }
123	
124	    // make sure targetFS has no change between from and the current states
125	    if (!checkNoChange(tgtFs, targetDir)) {
126	      // set the source path using the snapshot path
127	      context.setSourcePaths(Arrays.asList(getSnapshotPath(sourceDir,
128	          context.getToSnapshot())));
129	      return false;
130	    }
131	
132	    final String from = getSnapshotName(
133	        context.getFromSnapshot());
134	    final String to = getSnapshotName(
135	        context.getToSnapshot());
136	
137	    try {
138	      final FileStatus fromSnapshotStat =
139	          snapshotDiffFs.getFileStatus(getSnapshotPath(snapshotDiffDir, from));
140	
141	      final FileStatus toSnapshotStat =
142	          snapshotDiffFs.getFileStatus(getSnapshotPath(snapshotDiffDir, to));
143	
144	      if (isRdiff()) {
145	        // If fromSnapshot isn't current dir then do a time check
146	        if (!from.equals("")
147	            && fromSnapshotStat.getModificationTime() < toSnapshotStat
148	            .getModificationTime()) {
149	          throw new HadoopIllegalArgumentException("Snapshot " + from
150	              + " should be newer than " + to);
151	        }
152	      } else {
153	        // If toSnapshot isn't current dir then do a time check
154	        if(!to.equals("")
155	            && fromSnapshotStat.getModificationTime() > toSnapshotStat
156	            .getModificationTime()) {
157	          throw new HadoopIllegalArgumentException("Snapshot " + to
158	              + " should be newer than " + from);
159	        }
160	      }
161	    } catch (FileNotFoundException nfe) {
162	      throw new InvalidInputException("Input snapshot is not found", nfe);
163	    }
164	
165	    return true;
166	  }
167	
168	  public boolean sync() throws IOException {
169	    if (!preSyncCheck()) {
170	      return false;
171	    }
172	
173	    if (!getAllDiffs()) {
174	      return false;
175	    }
176	
177	    List<Path> sourcePaths = context.getSourcePaths();
178	    final Path sourceDir = sourcePaths.get(0);
179	    final Path targetDir = context.getTargetPath();
180	    final FileSystem tfs = targetDir.getFileSystem(conf);
181	
182	    Path tmpDir = null;
183	    try {
184	      tmpDir = createTargetTmpDir(tfs, targetDir);
185	      DiffInfo[] renameAndDeleteDiffs =
186	          getRenameAndDeleteDiffsForSync(targetDir);
187	      if (renameAndDeleteDiffs.length > 0) {
188	        // do the real sync work: deletion and rename
189	        syncDiff(renameAndDeleteDiffs, tfs, tmpDir);
190	      }
191	      return true;
192	    } catch (Exception e) {
193	      DistCp.LOG.warn("Failed to use snapshot diff for distcp", e);
194	      return false;
195	    } finally {
196	      deleteTargetTmpDir(tfs, tmpDir);
197	      // TODO: since we have tmp directory, we can support "undo" with failures
198	      // set the source path using the snapshot path
199	      context.setSourcePaths(Arrays.asList(getSnapshotPath(sourceDir,
200	          context.getToSnapshot())));
201	    }
202	  }
203	
204	  /**
205	   * Get all diffs from source directory snapshot diff report, put them into an
206	   * EnumMap whose key is DiffType, and value is a DiffInfo list. If there is
207	   * no entry for a given DiffType, the associated value will be an empty list.
208	   */
209	  private boolean getAllDiffs() throws IOException {
210	    Path ssDir = isRdiff()?
211	        context.getTargetPath() : context.getSourcePaths().get(0);
212	
213	    try {
214	      SnapshotDiffReport report = null;
215	      FileSystem fs = ssDir.getFileSystem(conf);
216	      final String from = getSnapshotName(context.getFromSnapshot());
217	      final String to = getSnapshotName(context.getToSnapshot());
218	      if (fs instanceof DistributedFileSystem) {
219	        DistributedFileSystem dfs = (DistributedFileSystem)fs;
220	        report = dfs.getSnapshotDiffReport(ssDir, from, to);
221	      } else if (fs instanceof WebHdfsFileSystem) {
222	        WebHdfsFileSystem webHdfs = (WebHdfsFileSystem)fs;
223	        report = webHdfs.getSnapshotDiffReport(ssDir, from, to);
224	      } else {
225	        throw new IllegalArgumentException("Unsupported file system: " +
226	            fs.getScheme() + "://. " +
227	            "Supported file systems: hdfs://, webhdfs:// and swebhdfs://.");
228	      }
229	
230	      this.diffMap = new EnumMap<>(SnapshotDiffReport.DiffType.class);

