69	              null);
70	        }
71	        mockRM.init(super.getConf());
72	        mockRM.start();
73	        try {
74	          mockRM.registerNode("h1:1234", 1024);
75	        } catch (Exception e) {
76	          Assert.fail(e.getMessage());
77	        }
78	        mockRMs.put(subClusterId, mockRM);
79	      }
