137	+/**
138	+ * Extending AutoCloseableLock such that the users can
139	+ * use a try-with-resource syntax.
140	+ */
141	+public class AutoCloseDataSetLock extends AutoCloseableLock {
142	+  private Lock lock;
143	+  private AutoCloseDataSetLock parentLock;
144	+  private DataNodeLockManager<AutoCloseDataSetLock> dataNodeLockManager;
145	+
146	+  public AutoCloseDataSetLock(Lock lock) {
147	+    this.lock = lock;
148	+  }
149	+
150	+  @Override
151	+  public void close() {
152	+    if (lock != null) {
153	+      lock.unlock();
154	+      if (dataNodeLockManager != null) {
155	+        dataNodeLockManager.hook();
156	+      }
157	+    } else {
158	+      LOG.error("Try to unlock null lock" +
159	+          StringUtils.getStackTrace(Thread.currentThread()));
160	+    }
161	+    if (parentLock != null) {
162	+      parentLock.close();
163	+    }
164	+  }
165	+
166	+  /**
167	+   * Actually acquire the lock.
168	+   */
169	+  public void lock() {
170	+    if (lock != null) {
171	+      lock.lock();
172	+      return;
173	+    }
174	+    LOG.error("Try to lock null lock" +
175	+        StringUtils.getStackTrace(Thread.currentThread()));
176	+  }
177	+
178	+  public void setParentLock(AutoCloseDataSetLock parent) {
179	+    if (parentLock == null) {
180	+      this.parentLock = parent;
181	+    }
182	+  }
