361	+import java.util.HashMap;
362	+import java.util.Stack;
363	+import java.util.concurrent.locks.ReentrantReadWriteLock;
364	+
365	+/**
366	+ * Class for maintain a set of lock for fsDataSetImpl.
367	+ */
368	+public class DataSetLockManager implements DataNodeLockManager<AutoCloseDataSetLock> {
369	+  public static final Log LOG = LogFactory.getLog(DataSetLockManager.class);
370	+  private final HashMap<String, TrackLog> threadCountMap = new HashMap<>();
371	+  private final LockMap lockMap = new LockMap();
372	+  private boolean isFair = true;
373	+  private final boolean openLockTrace;
374	+  private Exception lastException;
375	+
376	+  /**
377	+   * Class for maintain lockMap and is thread safe.
378	+   */
379	+  private class LockMap {
380	+    private final HashMap<String, AutoCloseDataSetLock> readlockMap = new HashMap<>();
381	+    private final HashMap<String, AutoCloseDataSetLock> writeLockMap = new HashMap<>();
382	+
383	+    public synchronized void addLock(String name, ReentrantReadWriteLock lock) {
384	+      AutoCloseDataSetLock readLock = new AutoCloseDataSetLock(lock.readLock());
385	+      AutoCloseDataSetLock writeLock = new AutoCloseDataSetLock(lock.writeLock());
386	+      if (openLockTrace) {
387	+        readLock.setDataNodeLockManager(DataSetLockManager.this);
388	+        writeLock.setDataNodeLockManager(DataSetLockManager.this);
389	+      }
390	+      readlockMap.putIfAbsent(name, readLock);
391	+      writeLockMap.putIfAbsent(name, writeLock);
392	+    }
393	+
394	+    public synchronized void removeLock(String name) {
395	+      if (!readlockMap.containsKey(name) || !writeLockMap.containsKey(name)) {
396	+        LOG.error("The lock " + name + " is not in LockMap");
397	+      }
398	+      readlockMap.remove(name);
399	+      writeLockMap.remove(name);
400	+    }
401	+
402	+    public synchronized AutoCloseDataSetLock getReadLock(String name) {
403	+      return readlockMap.get(name);
404	+    }
405	+
406	+    public synchronized AutoCloseDataSetLock getWriteLock(String name) {
407	+      return writeLockMap.get(name);
408	+    }
409	+  }
410	+
411	+  /**
412	+   * Generate lock order string concatenates with lock name.
413	+   * @param level which level lock want to acquire.
414	+   * @param resources lock name by lock order.
415	+   * @return lock order string concatenates with lock name.
416	+   */
417	+  private String generateLockName(LockLevel level, String... resources) {
418	+    if (resources.length == 1 && level == LockLevel.BLOCK_POOl) {
419	+      if (resources[0] == null) {
420	+        throw new IllegalArgumentException("acquire a null block pool lock");
421	+      }
422	+      return resources[0];
423	+    } else if (resources.length == 2 && level == LockLevel.VOLUME) {
424	+      if (resources[0] == null || resources[1] == null) {
425	+        throw new IllegalArgumentException("acquire a null bp lock : "
426	+            + resources[0] + "volume lock :" + resources[1]);
427	+      }
428	+      return resources[0] + resources[1];
429	+    } else {
430	+      throw new IllegalArgumentException("lock level do not match resource");
431	+    }
432	+  }
433	+
434	+  /**
435	+   * Class for record thread acquire lock stack trace and count.
436	+   */
437	+  private static class TrackLog {
438	+    private final Stack<Exception> logStack = new Stack<>();
439	+    private int lockCount = 0;
440	+    private final String threadName;
441	+
442	+    TrackLog(String threadName) {
443	+      this.threadName = threadName;
444	+      incrLockCount();
445	+    }
446	+
447	+    public void incrLockCount() {
448	+      logStack.push(new Exception("lock stack trace"));
449	+      lockCount += 1;
450	+    }
451	+
452	+    public void decrLockCount() {
453	+      logStack.pop();
454	+      lockCount -= 1;
455	+    }
456	+
457	+    public void showLockMessage() {
458	+      LOG.error("hold lock thread name is:" + threadName +
459	+          " hold count is:" + lockCount);
460	+      while (!logStack.isEmpty()) {
461	+        Exception e = logStack.pop();
462	+        LOG.error("lock stack ", e);
463	+      }
464	+    }
465	+
466	+    public boolean shouldClear() {
467	+      return lockCount == 1;
468	+    }
469	+  }
470	+
471	+  public DataSetLockManager(Configuration conf) {
472	+    this.isFair = conf.getBoolean(
473	+        DFSConfigKeys.DFS_DATANODE_LOCK_FAIR_KEY,
474	+        DFSConfigKeys.DFS_DATANODE_LOCK_FAIR_DEFAULT);
475	+    this.openLockTrace = conf.getBoolean(
476	+        DFSConfigKeys.DFS_DATANODE_LOCKMANAGER_TRACE,
477	+        DFSConfigKeys.DFS_DATANODE_LOCKMANAGER_TRACE_DEFAULT);
478	+  }
479	+
480	+  public DataSetLockManager() {
481	+    this.openLockTrace = true;
482	+  }
483	+
484	+  @Override
485	+  public AutoCloseDataSetLock readLock(LockLevel level, String... resources) {
486	+    if (level == LockLevel.BLOCK_POOl) {
487	+      return getReadLock(level, resources[0]);
488	+    } else {
489	+      AutoCloseDataSetLock bpLock = getReadLock(LockLevel.BLOCK_POOl, resources[0]);
490	+      AutoCloseDataSetLock volLock = getReadLock(level, resources);
491	+      volLock.setParentLock(bpLock);
492	+      if (openLockTrace) {
493	+        LOG.info("Sub lock " + resources[0] + resources[1] + " parent lock " +
494	+            resources[0]);
495	+      }
496	+      return volLock;
497	+    }
498	+  }
499	+
500	+  @Override
501	+  public AutoCloseDataSetLock writeLock(LockLevel level, String... resources) {
502	+    if (level == LockLevel.BLOCK_POOl) {
503	+      return getWriteLock(level, resources[0]);
504	+    } else {
505	+      AutoCloseDataSetLock bpLock = getReadLock(LockLevel.BLOCK_POOl, resources[0]);
506	+      AutoCloseDataSetLock volLock = getWriteLock(level, resources);
507	+      volLock.setParentLock(bpLock);
508	+      if (openLockTrace) {
509	+        LOG.info("Sub lock " + resources[0] + resources[1] + " parent lock " +
510	+            resources[0]);
511	+      }
512	+      return volLock;
513	+    }
514	+  }
515	+
516	+  /**
517	+   * Return a not null ReadLock.
518	+   */
519	+  private AutoCloseDataSetLock getReadLock(LockLevel level, String... resources) {
520	+    String lockName = generateLockName(level, resources);
521	+    AutoCloseDataSetLock lock = lockMap.getReadLock(lockName);
522	+    if (lock == null) {
523	+      LOG.warn("Ignore this error during dn restart: Not existing readLock "
524	+          + lockName);
525	+      lockMap.addLock(lockName, new ReentrantReadWriteLock(isFair));
526	+      lock = lockMap.getReadLock(lockName);
