@Test
public void testReconfigureBlockInvalidateLimit()
    throws ReconfigurationException {
  final NameNode nameNode = cluster.getNameNode();
  final DatanodeManager datanodeManager = nameNode.namesystem
      .getBlockManager().getDatanodeManager();

  // try invalid values
  try {
    nameNode.reconfigureProperty(DFS_BLOCK_INVALIDATE_LIMIT_KEY,
        "non-numeric");
    fail("Should not reach here!");
  } catch (ReconfigurationException e) {
    assertEquals("Could not change property dfs.block.invalidate.limit " +
        "from '500' to 'non-numeric'", e.getMessage());
  }

  try {
    nameNode.reconfigureProperty(DFS_BLOCK_INVALIDATE_LIMIT_KEY, "-1");
    fail("Should not reach here!");
  } catch (ReconfigurationException e) {
    assertEquals("Could not change property dfs.block.invalidate.limit " +
        "from '500' to '-1'", e.getMessage());
  }

  // change to a valid value
  nameNode.reconfigureProperty(DFS_BLOCK_INVALIDATE_LIMIT_KEY,
      Integer.toString(1000));
  assertEquals(DFS_BLOCK_INVALIDATE_LIMIT_KEY + " has wrong value", 1000,
      datanodeManager.getBlockInvalidateLimit());
  assertEquals(DFS_BLOCK_INVALIDATE_LIMIT_KEY + " has wrong value", "1000",
      nameNode.getConf().get(DFS_BLOCK_INVALIDATE_LIMIT_KEY));

  // revert to default
  nameNode.reconfigureProperty(DFS_BLOCK_INVALIDATE_LIMIT_KEY, null);
  assertEquals(DFS_BLOCK_INVALIDATE_LIMIT_KEY + " has wrong value",
      Math.max(20 * (int) datanodeManager.getHeartbeatInterval(),
          DFS_BLOCK_INVALIDATE_LIMIT_DEFAULT),
      datanodeManager.getBlockInvalidateLimit());
  assertEquals(DFS_BLOCK_INVALIDATE_LIMIT_KEY + " has wrong value", null,
      nameNode.getConf().get(DFS_BLOCK_INVALIDATE_LIMIT_KEY));
}

@Test
public void testBlockInvalidateLimitAfterReconfigured()

