40	public class ConfiguredRMFailoverProxyProvider<T>
41	    implements RMFailoverProxyProvider<T> {
42	  private static final Logger LOG =
43	      LoggerFactory.getLogger(ConfiguredRMFailoverProxyProvider.class);
44	
45	  private int currentProxyIndex = 0;
46	  Map<String, T> proxies = new HashMap<String, T>();
47	
48	  protected RMProxy<T> rmProxy;
49	  protected Class<T> protocol;
50	  protected YarnConfiguration conf;
51	  protected String[] rmServiceIds;
52	
53	  @Override
54	  public void init(Configuration configuration, RMProxy<T> rmProxy,
55	                    Class<T> protocol) {
56	    this.rmProxy = rmProxy;
57	    this.protocol = protocol;
58	    this.rmProxy.checkAllowedProtocols(this.protocol);
59	    this.conf = new YarnConfiguration(configuration);
60	    Collection<String> rmIds = HAUtil.getRMHAIds(conf);
61	    this.rmServiceIds = rmIds.toArray(new String[rmIds.size()]);
62	    conf.set(YarnConfiguration.RM_HA_ID, rmServiceIds[currentProxyIndex]);
63	
64	    conf.setInt(CommonConfigurationKeysPublic.IPC_CLIENT_CONNECT_MAX_RETRIES_KEY,
65	        conf.getInt(YarnConfiguration.CLIENT_FAILOVER_RETRIES,
66	            YarnConfiguration.DEFAULT_CLIENT_FAILOVER_RETRIES));
67	
68	    conf.setInt(CommonConfigurationKeysPublic.
69	        IPC_CLIENT_CONNECT_MAX_RETRIES_ON_SOCKET_TIMEOUTS_KEY,
70	        conf.getInt(YarnConfiguration.CLIENT_FAILOVER_RETRIES_ON_SOCKET_TIMEOUTS,
71	            YarnConfiguration.DEFAULT_CLIENT_FAILOVER_RETRIES_ON_SOCKET_TIMEOUTS));
72	  }
73	
74	  protected T getProxyInternal() {
75	    try {
76	      final InetSocketAddress rmAddress = rmProxy.getRMAddress(conf, protocol);
77	      return rmProxy.getProxy(conf, protocol, rmAddress);
78	    } catch (IOException ioe) {
79	      LOG.error("Unable to create proxy to the ResourceManager " +
80	          rmServiceIds[currentProxyIndex], ioe);
81	      return null;
82	    }
83	  }
84	
85	  @Override
86	  public synchronized ProxyInfo<T> getProxy() {
87	    String rmId = rmServiceIds[currentProxyIndex];
88	    T current = proxies.get(rmId);
89	    if (current == null) {
90	      current = getProxyInternal();
91	      proxies.put(rmId, current);
92	    }
93	    return new ProxyInfo<T>(current, rmId);
94	  }
95	
96	  @Override
97	  public synchronized void performFailover(T currentProxy) {
98	    currentProxyIndex = (currentProxyIndex + 1) % rmServiceIds.length;
99	    conf.set(YarnConfiguration.RM_HA_ID, rmServiceIds[currentProxyIndex]);
100	    LOG.info("Failing over to " + rmServiceIds[currentProxyIndex]);
101	  }
102	
103	  @Override
104	  public Class<T> getInterface() {
105	    return protocol;
106	  }
107	
108	  /**
109	   * Close all the proxy objects which have been opened over the lifetime of
110	   * this proxy provider.
111	   */
112	  @Override
113	  public synchronized void close() throws IOException {
114	    for (T proxy : proxies.values()) {
115	      if (proxy instanceof Closeable) {
116	        ((Closeable)proxy).close();
117	      } else {
118	        RPC.stopProxy(proxy);
119	      }
120	    }
121	  }
