237	  /** This class keeps track of a scheduled reportedBlock move */
238	  public class PendingMove {
239	    private DBlock reportedBlock;
240	    private Source source;
241	    private DDatanode proxySource;
242	    private StorageGroup target;
243	
244	    private PendingMove(Source source, StorageGroup target) {
245	      this.source = source;
246	      this.target = target;
247	    }
248	
249	    public DatanodeInfo getSource() {
250	      return source.getDatanodeInfo();
251	    }
252	
253	    @Override
254	    public String toString() {
255	      final Block b = reportedBlock != null ? reportedBlock.getBlock() : null;
256	      String bStr = b != null ? (b + " with size=" + b.getNumBytes() + " ")
257	          : " ";
258	      return bStr + "from " + source.getDisplayName() + " to " + target
259	          .getDisplayName() + " through " + (proxySource != null ? proxySource
260	          .datanode : "");
261	    }
262	
263	    /**
264	     * Choose a good block/blockGroup from source & Get reportedBlock from
265	     * the block & Choose a proxy source for the reportedBlock.
266	     * 
267	     * @return true if a block and its proxy are chosen; false otherwise
268	     */
269	    private boolean chooseBlockAndProxy() {
270	      // source and target must have the same storage type
271	      final StorageType t = source.getStorageType();
272	      // iterate all source's blocks until find a good one
273	      for (Iterator<DBlock> i = source.getBlockIterator(); i.hasNext();) {
274	        if (markMovedIfGoodBlock(i.next(), t)) {
275	          i.remove();
276	          return true;
277	        }
278	      }
279	      return false;
280	    }
281	
282	    /**
283	     * @return true if the given block is good for the tentative move.
284	     */
285	    private boolean markMovedIfGoodBlock(DBlock block, StorageType targetStorageType) {
286	      synchronized (block) {
287	        synchronized (movedBlocks) {
288	          if (isGoodBlockCandidate(source, target, targetStorageType, block)) {
289	            if (block instanceof DBlockStriped) {
290	              reportedBlock = ((DBlockStriped) block).getInternalBlock(source);
291	            } else {
292	              reportedBlock = block;
293	            }
294	            if (chooseProxySource()) {
295	              movedBlocks.put(block);
296	              if (LOG.isDebugEnabled()) {
297	                LOG.debug("Decided to move " + this);
298	              }
299	              return true;
300	            }
301	          }
302	        }
303	      }
304	      return false;
305	    }
306	
307	    /**
308	     * Choose a proxy source.
309	     * 
310	     * @return true if a proxy is found; otherwise false
311	     */
312	    private boolean chooseProxySource() {
313	      final DatanodeInfo targetDN = target.getDatanodeInfo();
314	      // if source and target are same nodes then no need of proxy
315	      if (source.getDatanodeInfo().equals(targetDN) && addTo(source)) {
316	        return true;
317	      }
318	      // if node group is supported, first try add nodes in the same node group
319	      if (cluster.isNodeGroupAware()) {
320	        for (StorageGroup loc : reportedBlock.getLocations()) {
321	          if (cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN)
322	              && addTo(loc)) {
323	            return true;
324	          }
325	        }
326	      }
327	      // check if there is replica which is on the same rack with the target
328	      for (StorageGroup loc : reportedBlock.getLocations()) {
329	        if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
330	          return true;
331	        }
332	      }
333	      // find out a non-busy replica
334	      for (StorageGroup loc : reportedBlock.getLocations()) {
335	        if (addTo(loc)) {
336	          return true;
337	        }
338	      }
339	      return false;
340	    }
341	
342	    /** add to a proxy source for specific reportedBlock movement */
343	    private boolean addTo(StorageGroup g) {
344	      final DDatanode dn = g.getDDatanode();
345	      if (dn.addPendingBlock(this)) {
346	        proxySource = dn;
347	        return true;
348	      }
349	      return false;
350	    }
351	
352	    /** Dispatch the move to the proxy source & wait for the response. */
353	    private void dispatch() {
354	      Socket sock = new Socket();
355	      DataOutputStream out = null;
356	      DataInputStream in = null;
357	      try {
358	        if (source.isIterationOver()){
359	          LOG.info("Cancel moving " + this +
360	              " as iteration is already cancelled due to" +
361	              " dfs.balancer.max-iteration-time is passed.");
362	          throw new IOException("Block move cancelled.");
363	        }
364	        LOG.info("Start moving " + this);
365	        assert !(reportedBlock instanceof DBlockStriped);
366	
367	        sock.connect(
368	            NetUtils.createSocketAddr(target.getDatanodeInfo().
369	                getXferAddr(Dispatcher.this.connectToDnViaHostname)),
370	                HdfsConstants.READ_TIMEOUT);
371	
372	        // Set read timeout so that it doesn't hang forever against
373	        // unresponsive nodes. Datanode normally sends IN_PROGRESS response
374	        // twice within the client read timeout period (every 30 seconds by
375	        // default). Here, we make it give up after 5 minutes of no response.
376	        sock.setSoTimeout(HdfsConstants.READ_TIMEOUT * 5);
377	        sock.setKeepAlive(true);
378	
379	        OutputStream unbufOut = sock.getOutputStream();
380	        InputStream unbufIn = sock.getInputStream();
381	        ExtendedBlock eb = new ExtendedBlock(nnc.getBlockpoolID(),
382	            reportedBlock.getBlock());
383	        final KeyManager km = nnc.getKeyManager(); 
384	        Token<BlockTokenIdentifier> accessToken = km.getAccessToken(eb,
385	            new StorageType[]{target.storageType}, new String[0]);
386	        IOStreamPair saslStreams = saslClient.socketSend(sock, unbufOut,
387	            unbufIn, km, accessToken, target.getDatanodeInfo());
388	        unbufOut = saslStreams.out;
389	        unbufIn = saslStreams.in;
390	        out = new DataOutputStream(new BufferedOutputStream(unbufOut,
391	            ioFileBufferSize));
392	        in = new DataInputStream(new BufferedInputStream(unbufIn,
393	            ioFileBufferSize));
394	
395	        sendRequest(out, eb, accessToken);
396	        receiveResponse(in);
397	        nnc.addBytesMoved(reportedBlock.getNumBytes());
398	        target.getDDatanode().setHasSuccess();
399	        LOG.info("Successfully moved " + this);
400	      } catch (IOException e) {
401	        LOG.warn("Failed to move " + this, e);
402	        nnc.getBlocksFailed().incrementAndGet();
403	        target.getDDatanode().setHasFailure();
404	        // Check that the failure is due to block pinning errors.
405	        if (e instanceof BlockPinningException) {
406	          // Pinned block can't be moved. Add this block into failure list.
407	          // Later in the next iteration mover will exclude these blocks from
408	          // pending moves.
409	          target.getDDatanode().addBlockPinningFailures(
410	              this.reportedBlock.getBlock().getBlockId(), this.getSource());
411	          return;
412	        }
413	
414	        // Proxy or target may have some issues, delay before using these nodes
415	        // further in order to avoid a potential storm of "threads quota
416	        // exceeded" warnings when the dispatcher gets out of sync with work
417	        // going on in datanodes.
418	        proxySource.activateDelay(delayAfterErrors);
419	        target.getDDatanode().activateDelay(delayAfterErrors);
420	      } finally {
421	        IOUtils.closeStream(out);
422	        IOUtils.closeStream(in);
423	        IOUtils.closeSocket(sock);
424	
425	        proxySource.removePendingBlock(this);
426	        target.getDDatanode().removePendingBlock(this);
427	
428	        synchronized (this) {
429	          reset();

