490	  public static class DBlockStriped extends DBlock {
491	
492	    final byte[] indices;
493	    final short dataBlockNum;
494	    final int cellSize;
495	
496	    public DBlockStriped(Block block, byte[] indices, short dataBlockNum,
497	        int cellSize) {
498	      super(block);
499	      this.indices = indices;
500	      this.dataBlockNum = dataBlockNum;
501	      this.cellSize = cellSize;
502	    }
503	
504	    public DBlock getInternalBlock(StorageGroup storage) {
505	      int idxInLocs = locations.indexOf(storage);
506	      if (idxInLocs == -1) {
507	        return null;
508	      }
509	      byte idxInGroup = indices[idxInLocs];
510	      long blkId = getBlock().getBlockId() + idxInGroup;
511	      long numBytes = getInternalBlockLength(getNumBytes(), cellSize,
512	          dataBlockNum, idxInGroup);
513	      Block blk = new Block(getBlock());
514	      blk.setBlockId(blkId);
515	      blk.setNumBytes(numBytes);
516	      DBlock dblk = new DBlock(blk);
517	      dblk.addLocation(storage);
518	      return dblk;
519	    }
520	
521	    @Override
522	    public long getNumBytes(StorageGroup storage) {
523	      return getInternalBlock(storage).getNumBytes();
524	    }
