542	  /** A class that keeps track of a datanode. */
543	  public static class DDatanode {
544	
545	    /** A group of storages in a datanode with the same storage type. */
546	    public class StorageGroup {
547	      final StorageType storageType;
548	      final long maxSize2Move;
549	      private long scheduledSize = 0L;
550	
551	      private StorageGroup(StorageType storageType, long maxSize2Move) {
552	        this.storageType = storageType;
553	        this.maxSize2Move = maxSize2Move;
554	      }
555	      
556	      public StorageType getStorageType() {
557	        return storageType;
558	      }
559	
560	      private DDatanode getDDatanode() {
561	        return DDatanode.this;
562	      }
563	
564	      public DatanodeInfo getDatanodeInfo() {
565	        return DDatanode.this.datanode;
566	      }
567	
568	      /** Decide if still need to move more bytes */
569	      boolean hasSpaceForScheduling() {
570	        return hasSpaceForScheduling(0L);
571	      }
572	
573	      synchronized boolean hasSpaceForScheduling(long size) {
574	        return availableSizeToMove() > size;
575	      }
576	
577	      /** @return the total number of bytes that need to be moved */
578	      synchronized long availableSizeToMove() {
579	        return maxSize2Move - scheduledSize;
580	      }
581	
582	      /** increment scheduled size */
583	      public synchronized void incScheduledSize(long size) {
584	        scheduledSize += size;
585	      }
586	
587	      /** @return scheduled size */
588	      synchronized long getScheduledSize() {
589	        return scheduledSize;
590	      }
591	
592	      /** Reset scheduled size to zero. */
