40	+      String fromSnapshotName, String toSnapshotName, String snapshotDiffStartPath,
41	+      int snapshotDiffIndex) throws IOException {
42	+    statistics.incrementReadOps(1);
43	+    storageStatistics.incrementOpCounter(OpType.GET_SNAPSHOT_DIFF);
44	+    Path absF = fixRelativePart(snapshotDir);
45	+    return new FileSystemLinkResolver<SnapshotDiffReportListing>() {
46	+
47	+      @Override
48	+      public SnapshotDiffReportListing doCall(final Path p) throws IOException {
49	+        return dfs.getSnapshotDiffReportListing(getPathName(p), fromSnapshotName, toSnapshotName,
50	+            DFSUtilClient.string2Bytes(snapshotDiffStartPath), snapshotDiffIndex);
51	+      }
52	+
53	+      @Override
54	+      public SnapshotDiffReportListing next(final FileSystem fs, final Path p)
55	+          throws IOException {
56	+        if (fs instanceof DistributedFileSystem) {
57	+          DistributedFileSystem distributedFileSystem = (DistributedFileSystem)fs;
58	+          distributedFileSystem.getSnapshotDiffReportListing(p, fromSnapshotName, toSnapshotName,
59	+              snapshotDiffStartPath, snapshotDiffIndex);
60	+        } else {
61	+          throw new UnsupportedOperationException("Cannot perform snapshot"
62	+              + " operations on a symlink to a non-DistributedFileSystem: "
63	+              + snapshotDir + " -> " + p);
64	+        }
65	+        return null;
66	+      }
