29	/**
30	 * Abstract command to enable sub copy commands run with multi-thread.
31	 */
32	public abstract class CopyCommandWithMultiThread
33	    extends CommandWithDestination {
34	
35	  private int threadCount = 1;
36	  private ThreadPoolExecutor executor = null;
37	  private int threadPoolQueueSize = DEFAULT_QUEUE_SIZE;
38	
39	  public static final int DEFAULT_QUEUE_SIZE = 1024;
40	
41	  /**
42	   * set thread count by option value, if the value less than 1,
43	   * use 1 instead.
44	   *
45	   * @param optValue option value
46	   */
47	  protected void setThreadCount(String optValue) {
48	    if (optValue != null) {
49	      threadCount = Math.max(Integer.parseInt(optValue), 1);
50	    }
51	  }
52	
53	  /**
54	   * set thread pool queue size by option value, if the value less than 1,
55	   * use DEFAULT_QUEUE_SIZE instead.
56	   *
57	   * @param optValue option value
58	   */
59	  protected void setThreadPoolQueueSize(String optValue) {
60	    if (optValue != null) {
61	      int size = Integer.parseInt(optValue);
62	      threadPoolQueueSize = size < 1 ? DEFAULT_QUEUE_SIZE : size;
63	    }
64	  }
65	
66	  @VisibleForTesting
67	  protected int getThreadCount() {
68	    return this.threadCount;
69	  }
70	
71	  @VisibleForTesting
72	  protected int getThreadPoolQueueSize() {
73	    return this.threadPoolQueueSize;
74	  }
75	
76	  @VisibleForTesting
77	  protected ThreadPoolExecutor getExecutor() {
78	    return this.executor;
79	  }
80	
81	  @Override
82	  protected void processArguments(LinkedList<PathData> args)
83	      throws IOException {
84	
85	    if (isMultiThreadNecessary(args)) {
86	      initThreadPoolExecutor();
87	    }
88	
89	    super.processArguments(args);
90	
91	    if (executor != null) {
92	      waitForCompletion();
93	    }
94	  }
95	
96	  // if thread count is 1 or the source is only one single file,
97	  // don't init executor to avoid threading overhead.
98	  @VisibleForTesting
99	  protected boolean isMultiThreadNecessary(LinkedList<PathData> args)
100	      throws IOException {
101	    return this.threadCount > 1 && hasMoreThanOneSourcePaths(args);
102	  }
103	
104	  // check if source is only one single file.
105	  private boolean hasMoreThanOneSourcePaths(LinkedList<PathData> args)
106	      throws IOException {
107	    if (args.size() > 1) {
108	      return true;
109	    }
110	    if (args.size() == 1) {
111	      PathData src = args.get(0);
112	      if (src.stat == null) {
113	        src.refreshStatus();
114	      }
115	      return isPathRecursable(src);
116	    }
117	    return false;
118	  }
119	
120	  private void initThreadPoolExecutor() {
121	    executor =
122	        new ThreadPoolExecutor(threadCount, threadCount, 1, TimeUnit.SECONDS,
123	            new ArrayBlockingQueue<>(threadPoolQueueSize),
124	            new ThreadPoolExecutor.CallerRunsPolicy());
125	  }
126	
127	  private void waitForCompletion() {
128	    if (executor != null) {
129	      executor.shutdown();
130	      try {
131	        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MINUTES);
132	      } catch (InterruptedException e) {
133	        executor.shutdownNow();
134	        displayError(e);
135	        Thread.currentThread().interrupt();
136	      }
137	    }
138	  }
139	
140	  @Override
141	  protected void copyFileToTarget(PathData src, PathData target)
142	      throws IOException {
143	    if (executor == null) {
144	      super.copyFileToTarget(src, target);
145	    } else {
146	      executor.submit(() -> {
147	        try {
148	          super.copyFileToTarget(src, target);
149	        } catch (IOException e) {
150	          displayError(e);
151	        }
152	      });
153	    }
154	  }
155	}

