      int cellSize) {
    super(block);
    this.indices = indices;
    this.dataBlockNum = dataBlockNum;
    this.cellSize = cellSize;
  }

  /**
   * Recalculate the internal block indices to keep them aligned with the
   * remaining locations after some locations are excluded, e.g. their
   * storages are unknown to the storage group map.
   */
  public void adjustIndices(List<Byte> blockIndices) {
    byte[] newIndices = new byte[blockIndices.size()];
    for (int i = 0; i < newIndices.length; i++) {
      newIndices[i] = blockIndices.get(i);
    }
    this.indices = newIndices;
  }

