  Block aBlockGroup = new Block(blockId,
      ecPolicy.getCellSize() * (ecPolicy.getNumDataUnits() - 1), 0);
  BlockInfoStriped aBlockInfoStriped = new BlockInfoStriped(aBlockGroup, ecPolicy);

